/**
 * Waits for a new compose window to open. This assumes you have already called
 * `promise_new_window("msgcompose");` and the command to open
 * the compose window itself.
 *
 * @param {Promise} composePromise - The returned promise from `promise_new_window`.
 * @returns {Promise<Window>} The loaded window of type "msgcompose".
 */
export async function compose_window_ready(composePromise) {
  const replyWindow = await composePromise;
  return _wait_for_compose_window(replyWindow);
}

/**
 * Wait for the window to be active.
 *
 * @param {window} win - The window to wait for.
 * @returns {Promise<Window>} The loaded window;
 */
async function _wait_for_compose_window(win) {
  if (Services.focus.activeWindow != win) {
    let focusTimeoutId;
    const focusTimeout = new Promise(resolve => {
      focusTimeoutId = win.setTimeout(() => {
        Assert.report(
          false,
          undefined,
          undefined,
          `Will force focus to ${win.location}`
        );
        win.focus();
        resolve();
      }, 5000);
    });
    await Promise.race([
      BrowserTestUtils.waitForEvent(win, "activate"),
      focusTimeout,
    ]);
    win.clearTimeout(focusTimeoutId);
    Assert.report(
      false,
      undefined,
      undefined,
      `${Services.focus.activeWindow?.location} now active - ${Services.focus.focusedWindow?.location} has focus`
    );
  }
  await TestUtils.waitForCondition(
    () => win.composeEditorReady,
    "waiting for the compose editor to be ready"
  );
  await new Promise(resolve => win.setTimeout(resolve));
  return win;
}
